/* Secret app. It only appears after the right command is typed in Terminal. */
(function () {
  const OS = window.BrowOS;
  const PAGE = "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n    <meta charset=\"UTF-8\">\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n    <title>Shadow Cipher Operative Hub</title>\n    <!-- Tailwind CSS -->\n    <script src=\"https://cdn.tailwindcss.com\"></script>\n    <!-- Font Awesome Icons -->\n    <link rel=\"stylesheet\" href=\"https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.4.0/css/all.min.css\">\n    <!-- Google Fonts -->\n    <link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n    <link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin>\n    <link href=\"https://fonts.googleapis.com/css2?family=Fira+Code:wght@400;600&family=Inter:wght@300;400;600;700&display=swap\" rel=\"stylesheet\">\n\n    <script>\n        tailwind.config = {\n            theme: {\n                extend: {\n                    fontFamily: {\n                        sans: ['Inter', 'sans-serif'],\n                        mono: ['Fira Code', 'monospace'],\n                    },\n                    colors: {\n                        shadow: {\n                            900: '#0B0F19',\n                            800: '#111827',\n                            700: '#1F2937',\n                            accent: '#8B5CF6', // Purple\n                            glow: '#A78BFA',\n                            emerald: '#10B981'\n                        }\n                    }\n                }\n            }\n        }\n    </script>\n    <style>\n        /* Custom scrollbars */\n        ::-webkit-scrollbar {\n            width: 8px;\n            height: 8px;\n        }\n        ::-webkit-scrollbar-track {\n            background: #0B0F19;\n        }\n        ::-webkit-scrollbar-thumb {\n            background: #1F2937;\n            border-radius: 4px;\n        }\n        ::-webkit-scrollbar-thumb:hover {\n            background: #374151;\n        }\n        .glow-effect {\n            box-shadow: 0 0 20px -5px rgba(139, 92, 246, 0.3);\n        }\n        .letter-card {\n            transition: all 0.2s ease;\n        }\n        .letter-card.active {\n            background-color: #8B5CF6 !important;\n            color: #ffffff !important;\n            transform: scale(1.08);\n            box-shadow: 0 0 12px rgba(139, 92, 246, 0.6);\n        }\n    </style>\n</head>\n<body class=\"bg-shadow-900 text-slate-100 font-sans min-h-screen flex flex-col justify-between selection:bg-purple-500 selection:text-white\">\n\n    <!-- Toast Notification -->\n    <div id=\"toast\" class=\"fixed top-5 right-5 z-50 transform translate-y-[-100px] opacity-0 transition-all duration-300 flex items-center gap-3 bg-emerald-600 text-white px-5 py-3 rounded-xl shadow-2xl font-medium border border-emerald-400/30\">\n        <i class=\"fa-solid fa-circle-check text-lg\"></i>\n        <span id=\"toast-message\">Copied to clipboard!</span>\n    </div>\n\n    <!-- Header Navigation -->\n    <header class=\"border-b border-slate-800 bg-shadow-800/80 backdrop-blur sticky top-0 z-40\">\n        <div class=\"max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-4 flex flex-wrap items-center justify-between gap-4\">\n            <div class=\"flex items-center gap-3\">\n                <div class=\"w-10 h-10 rounded-xl bg-purple-600/20 border border-purple-500/40 flex items-center justify-center text-purple-400 glow-effect\">\n                    <i class=\"fa-solid fa-user-ninja text-xl\"></i>\n                </div>\n                <div>\n                    <h1 class=\"text-xl font-bold tracking-wide bg-gradient-to-r from-purple-400 to-indigo-300 bg-clip-text text-transparent\">SHADOW CIPHER</h1>\n                    <p class=\"text-xs text-slate-400\">Operative Translation Suite</p>\n                </div>\n            </div>\n\n            <div class=\"flex items-center gap-2 bg-slate-900/80 p-1.5 rounded-xl border border-slate-800\">\n                <button id=\"mode-encode-btn\" onclick=\"setMode('encode')\" class=\"px-4 py-2 rounded-lg text-sm font-semibold transition-all duration-200 bg-purple-600 text-white shadow-lg flex items-center gap-2\">\n                    <i class=\"fa-solid fa-lock text-xs\"></i>\n                    <span>Encode (English &rarr; Shadow)</span>\n                </button>\n                <button id=\"mode-decode-btn\" onclick=\"setMode('decode')\" class=\"px-4 py-2 rounded-lg text-sm font-semibold transition-all duration-200 text-slate-400 hover:text-white hover:bg-slate-800 flex items-center gap-2\">\n                    <i class=\"fa-solid fa-key text-xs\"></i>\n                    <span>Decode (Shadow &rarr; English)</span>\n                </button>\n            </div>\n        </div>\n    </header>\n\n    <!-- Main Content Grid -->\n    <main class=\"max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8 w-full flex-1 grid grid-cols-1 lg:grid-cols-12 gap-8\">\n\n        <!-- Translation Interface (Left Column - 7 cols) -->\n        <section class=\"lg:col-span-7 flex flex-col gap-6\">\n\n            <!-- Controls bar -->\n            <div class=\"flex items-center justify-between bg-shadow-800 p-4 rounded-2xl border border-slate-800\">\n                <div class=\"flex items-center gap-2\">\n                    <span id=\"current-mode-badge\" class=\"px-3 py-1 rounded-full text-xs font-mono font-semibold bg-purple-500/20 text-purple-300 border border-purple-500/30 uppercase\">\n                        MODE: ENCRYPT\n                    </span>\n                </div>\n                <div class=\"flex items-center gap-2\">\n                    <button onclick=\"swapTexts()\" title=\"Swap Input & Output\" class=\"p-2.5 rounded-xl bg-slate-800 text-slate-300 hover:bg-slate-700 hover:text-white transition border border-slate-700\">\n                        <i class=\"fa-solid fa-arrow-right-arrow-left\"></i>\n                    </button>\n                    <button onclick=\"clearAll()\" title=\"Clear Text\" class=\"p-2.5 rounded-xl bg-slate-800 text-rose-400 hover:bg-rose-500/20 transition border border-slate-700\">\n                        <i class=\"fa-solid fa-trash-can\"></i>\n                    </button>\n                </div>\n            </div>\n\n            <!-- Input Box -->\n            <div class=\"bg-shadow-800 rounded-2xl border border-slate-800 p-5 flex flex-col gap-3 focus-within:border-purple-500/50 transition\">\n                <div class=\"flex items-center justify-between\">\n                    <label id=\"input-label\" for=\"input-text\" class=\"text-xs font-bold font-mono tracking-wider text-slate-400 uppercase\">\n                        Plain English Input\n                    </label>\n                    <span id=\"input-char-count\" class=\"text-xs font-mono text-slate-500\">0 chars</span>\n                </div>\n                <textarea id=\"input-text\" rows=\"5\" placeholder=\"Type or paste your message here...\"\n                    class=\"w-full bg-transparent text-slate-100 placeholder-slate-600 font-mono resize-y focus:outline-none text-base sm:text-lg leading-relaxed\"></textarea>\n            </div>\n\n            <!-- Translation Arrow Divider -->\n            <div class=\"flex justify-center -my-2\">\n                <div class=\"w-10 h-10 rounded-full bg-slate-800 border border-slate-700 flex items-center justify-center text-purple-400 shadow-md\">\n                    <i id=\"direction-arrow\" class=\"fa-solid fa-arrow-down transition-transform duration-300\"></i>\n                </div>\n            </div>\n\n            <!-- Output Box -->\n            <div class=\"bg-shadow-800 rounded-2xl border border-purple-900/30 p-5 flex flex-col gap-3 relative glow-effect\">\n                <div class=\"flex items-center justify-between\">\n                    <label id=\"output-label\" for=\"output-text\" class=\"text-xs font-bold font-mono tracking-wider text-purple-400 uppercase flex items-center gap-2\">\n                        <i class=\"fa-solid fa-shield-halved\"></i>\n                        Shadow Cipher Output\n                    </label>\n                    <div class=\"flex items-center gap-3\">\n                        <span id=\"output-char-count\" class=\"text-xs font-mono text-slate-500\">0 chars</span>\n                        <button onclick=\"copyOutput()\" class=\"px-3 py-1.5 rounded-lg bg-purple-600/30 text-purple-300 hover:bg-purple-600 hover:text-white border border-purple-500/40 text-xs font-semibold transition flex items-center gap-1.5\">\n                            <i class=\"fa-solid fa-copy\"></i>\n                            <span>Copy</span>\n                        </button>\n                    </div>\n                </div>\n                <textarea id=\"output-text\" rows=\"5\" readonly placeholder=\"Translated output will appear here automatically...\"\n                    class=\"w-full bg-transparent text-purple-200 font-mono resize-y focus:outline-none text-base sm:text-lg leading-relaxed cursor-default\"></textarea>\n            </div>\n\n            <!-- Quick Preset Buttons -->\n            <div class=\"bg-shadow-800/60 p-4 rounded-2xl border border-slate-800/80 flex flex-wrap items-center gap-2\">\n                <span class=\"text-xs text-slate-400 font-medium mr-2\">Try quick test:</span>\n                <button onclick=\"loadSample('Hello Secret Operative!')\" class=\"text-xs px-3 py-1.5 rounded-lg bg-slate-800 text-slate-300 hover:bg-slate-700 hover:text-white border border-slate-700/60 transition\">\"Hello Secret Operative!\"</button>\n                <button onclick=\"loadSample('Meet at midnight in the park')\" class=\"text-xs px-3 py-1.5 rounded-lg bg-slate-800 text-slate-300 hover:bg-slate-700 hover:text-white border border-slate-700/60 transition\">\"Meet at midnight...\"</button>\n                <button onclick=\"loadSample('Fouzan Faizal')\" class=\"text-xs px-3 py-1.5 rounded-lg bg-slate-800 text-slate-300 hover:bg-slate-700 hover:text-white border border-slate-700/60 transition\">\"Fouzan Faizal\"</button>\n            </div>\n\n        </section>\n\n        <!-- Interactive Reference Chart (Right Column - 5 cols) -->\n        <section class=\"lg:col-span-5 flex flex-col gap-6\">\n\n            <div class=\"bg-shadow-800 rounded-2xl border border-slate-800 p-6 flex flex-col gap-5 h-full\">\n                <div class=\"flex items-center justify-between border-b border-slate-700/50 pb-4\">\n                    <div>\n                        <h2 class=\"text-lg font-bold text-slate-100 flex items-center gap-2\">\n                            <i class=\"fa-solid fa-book-bookmark text-purple-400\"></i>\n                            Cipher Key Reference\n                        </h2>\n                        <p class=\"text-xs text-slate-400 mt-1\">Plain Alphabet &rarr; Shadow Cipher Code</p>\n                    </div>\n                    <button onclick=\"toggleKeyEditor()\" class=\"text-xs px-2.5 py-1.5 rounded-lg bg-slate-700/50 text-slate-300 hover:bg-slate-700 hover:text-white transition flex items-center gap-1\">\n                        <i class=\"fa-solid fa-pen-to-square\"></i>\n                        <span>Edit Key</span>\n                    </button>\n                </div>\n\n                <!-- Grid of alphabet cards -->\n                <div id=\"alphabet-grid\" class=\"grid grid-cols-2 sm:grid-cols-3 gap-2.5 max-h-[500px] overflow-y-auto pr-1\">\n                    <!-- Javascript populates 26 letter cards dynamically -->\n                </div>\n\n                <!-- Quick info card -->\n                <div class=\"mt-auto bg-slate-900/90 p-4 rounded-xl border border-slate-800 text-xs text-slate-400 leading-relaxed flex items-start gap-3\">\n                    <i class=\"fa-solid fa-lightbulb text-amber-400 text-base mt-0.5\"></i>\n                    <div>\n                        <strong class=\"text-slate-200\">Operative Tip:</strong> Case sensitivity, punctuation, spaces, and numbers stay exactly as written. Typing above highlights matched letters in this key real-time!\n                    </div>\n                </div>\n            </div>\n\n        </section>\n\n    </main>\n\n    <!-- Custom Key Editor Modal -->\n    <div id=\"editor-modal\" class=\"fixed inset-0 z-50 bg-black/80 backdrop-blur-sm flex items-center justify-center p-4 hidden\">\n        <div class=\"bg-shadow-800 border border-slate-700 rounded-2xl max-w-lg w-full p-6 shadow-2xl flex flex-col gap-5 max-h-[90vh] overflow-y-auto\">\n            <div class=\"flex items-center justify-between border-b border-slate-700 pb-3\">\n                <h3 class=\"text-lg font-bold text-purple-300 flex items-center gap-2\">\n                    <i class=\"fa-solid fa-sliders\"></i>\n                    Customize Shadow Key\n                </h3>\n                <button onclick=\"toggleKeyEditor()\" class=\"text-slate-400 hover:text-white text-lg\">\n                    <i class=\"fa-solid fa-xmark\"></i>\n                </button>\n            </div>\n\n            <p class=\"text-xs text-slate-400\">Modify any letter mapping below. Ensure each letter maps to a unique letter for proper decoding.</p>\n\n            <div id=\"editor-grid\" class=\"grid grid-cols-2 sm:grid-cols-3 gap-3\">\n                <!-- Javascript builds input fields for each letter -->\n            </div>\n\n            <div class=\"flex items-center justify-between border-t border-slate-700 pt-4 gap-3\">\n                <button onclick=\"resetDefaultKey()\" class=\"px-4 py-2 rounded-xl bg-slate-700 text-slate-300 hover:bg-slate-600 hover:text-white text-xs font-semibold transition\">\n                    Reset Default Key\n                </button>\n                <div class=\"flex items-center gap-2\">\n                    <button onclick=\"toggleKeyEditor()\" class=\"px-4 py-2 rounded-xl bg-slate-800 text-slate-300 hover:bg-slate-700 text-xs font-semibold transition\">\n                        Cancel\n                    </button>\n                    <button onclick=\"saveCustomKey()\" class=\"px-5 py-2 rounded-xl bg-purple-600 text-white hover:bg-purple-500 text-xs font-semibold transition shadow-lg\">\n                        Save Changes\n                    </button>\n                </div>\n            </div>\n        </div>\n    </div>\n\n    <!-- Footer -->\n    <footer class=\"border-t border-slate-800/80 bg-shadow-900 py-6 text-center text-xs text-slate-500\">\n        <div class=\"max-w-7xl mx-auto px-4 flex flex-col sm:flex-row items-center justify-between gap-3\">\n            <div>Shadow Cipher Operative Hub &bull; Top Secret Encryption</div>\n            <div class=\"flex items-center gap-4 text-slate-400\">\n                <span class=\"flex items-center gap-1\"><i class=\"fa-solid fa-shield text-purple-400\"></i> Client-Side Processing</span>\n                <span class=\"flex items-center gap-1\"><i class=\"fa-solid fa-bolt text-amber-400\"></i> Instant Sync</span>\n            </div>\n        </div>\n    </footer>\n\n    <!-- App Logic -->\n    <script>\n        // Standard Default Shadow Cipher Mapping\n        const DEFAULT_CIPHER_MAP = {\n            'A': 'S', 'B': 'X', 'C': 'Q', 'D': 'F', 'E': 'M',\n            'F': 'V', 'G': 'P', 'H': 'L', 'I': 'T', 'J': 'Z',\n            'K': 'W', 'L': 'R', 'M': 'U', 'N': 'Y', 'O': 'E',\n            'P': 'G', 'Q': 'K', 'R': 'N', 'S': 'I', 'T': 'O',\n            'U': 'D', 'V': 'A', 'W': 'H', 'X': 'B', 'Y': 'C', 'Z': 'J'\n        };\n\n        // Current Active Key\n        let cipherMap = { ...DEFAULT_CIPHER_MAP };\n        let reverseMap = {};\n\n        // App state\n        let currentMode = 'encode'; // 'encode' or 'decode'\n\n        // Initialize maps\n        function updateReverseMap() {\n            reverseMap = {};\n            for (let [plain, cipher] of Object.entries(cipherMap)) {\n                reverseMap[cipher] = plain;\n            }\n        }\n\n        // Setup DOM Elements\n        const inputText = document.getElementById('input-text');\n        const outputText = document.getElementById('output-text');\n        const modeEncodeBtn = document.getElementById('mode-encode-btn');\n        const modeDecodeBtn = document.getElementById('mode-decode-btn');\n        const currentModeBadge = document.getElementById('current-mode-badge');\n        const inputLabel = document.getElementById('input-label');\n        const outputLabel = document.getElementById('output-label');\n        const directionArrow = document.getElementById('direction-arrow');\n        const inputCharCount = document.getElementById('input-char-count');\n        const outputCharCount = document.getElementById('output-char-count');\n        const alphabetGrid = document.getElementById('alphabet-grid');\n\n        // On Page Load\n        window.addEventListener('DOMContentLoaded', () => {\n            updateReverseMap();\n            renderAlphabetGrid();\n            \n            // Listeners\n            inputText.addEventListener('input', handleTranslate);\n        });\n\n        // Set Mode (Encode or Decode)\n        function setMode(mode) {\n            currentMode = mode;\n            if (mode === 'encode') {\n                modeEncodeBtn.className = \"px-4 py-2 rounded-lg text-sm font-semibold transition-all duration-200 bg-purple-600 text-white shadow-lg flex items-center gap-2\";\n                modeDecodeBtn.className = \"px-4 py-2 rounded-lg text-sm font-semibold transition-all duration-200 text-slate-400 hover:text-white hover:bg-slate-800 flex items-center gap-2\";\n                \n                currentModeBadge.textContent = \"MODE: ENCRYPT\";\n                currentModeBadge.className = \"px-3 py-1 rounded-full text-xs font-mono font-semibold bg-purple-500/20 text-purple-300 border border-purple-500/30 uppercase\";\n                \n                inputLabel.textContent = \"Plain English Input\";\n                outputLabel.innerHTML = '<i class=\"fa-solid fa-shield-halved\"></i> Shadow Cipher Output';\n                directionArrow.className = \"fa-solid fa-arrow-down transition-transform duration-300 rotate-0\";\n                \n                inputText.placeholder = \"Type plain text to encrypt...\";\n            } else {\n                modeDecodeBtn.className = \"px-4 py-2 rounded-lg text-sm font-semibold transition-all duration-200 bg-purple-600 text-white shadow-lg flex items-center gap-2\";\n                modeEncodeBtn.className = \"px-4 py-2 rounded-lg text-sm font-semibold transition-all duration-200 text-slate-400 hover:text-white hover:bg-slate-800 flex items-center gap-2\";\n                \n                currentModeBadge.textContent = \"MODE: DECRYPT\";\n                currentModeBadge.className = \"px-3 py-1 rounded-full text-xs font-mono font-semibold bg-emerald-500/20 text-emerald-300 border border-emerald-500/30 uppercase\";\n                \n                inputLabel.textContent = \"Shadow Cipher Input\";\n                outputLabel.innerHTML = '<i class=\"fa-solid fa-key text-emerald-400\"></i> Plain English Output';\n                directionArrow.className = \"fa-solid fa-arrow-down transition-transform duration-300 rotate-180\";\n                \n                inputText.placeholder = \"Type cipher text to decrypt...\";\n            }\n\n            handleTranslate();\n            renderAlphabetGrid();\n        }\n\n        // Translation Core Function\n        function handleTranslate() {\n            const val = inputText.value;\n            inputCharCount.textContent = `${val.length} chars`;\n\n            let result = '';\n            const usedLetters = new Set();\n\n            for (let i = 0; i < val.length; i++) {\n                const char = val[i];\n                const upperChar = char.toUpperCase();\n                const isUpper = char === upperChar && char !== char.toLowerCase();\n\n                let mapped = char;\n\n                if (currentMode === 'encode') {\n                    if (cipherMap[upperChar]) {\n                        mapped = isUpper ? cipherMap[upperChar] : cipherMap[upperChar].toLowerCase();\n                        usedLetters.add(upperChar);\n                    }\n                } else {\n                    if (reverseMap[upperChar]) {\n                        mapped = isUpper ? reverseMap[upperChar] : reverseMap[upperChar].toLowerCase();\n                        usedLetters.add(upperChar); // In decode mode, highlight cipher letters\n                    }\n                }\n                result += mapped;\n            }\n\n            outputText.value = result;\n            outputCharCount.textContent = `${result.length} chars`;\n\n            highlightLettersInGrid(usedLetters);\n        }\n\n        // Render Reference Grid\n        function renderAlphabetGrid() {\n            alphabetGrid.innerHTML = '';\n            const alphabet = \"ABCDEFGHIJKLMNOPQRSTUVWXYZ\".split('');\n\n            alphabet.forEach(letter => {\n                const cipher = cipherMap[letter] || '?';\n                const card = document.createElement('div');\n                card.id = `card-${letter}`;\n                card.className = \"letter-card bg-slate-900/80 border border-slate-800 rounded-xl p-2.5 flex items-center justify-between font-mono text-sm\";\n                \n                card.innerHTML = `\n                    <span class=\"text-slate-400 font-semibold\">${letter}</span>\n                    <i class=\"fa-solid fa-angle-right text-[10px] text-slate-600\"></i>\n                    <span class=\"text-purple-400 font-bold\">${cipher}</span>\n                `;\n                alphabetGrid.appendChild(card);\n            });\n        }\n\n        // Highlight actively typed letters\n        function highlightLettersInGrid(usedLettersSet) {\n            const alphabet = \"ABCDEFGHIJKLMNOPQRSTUVWXYZ\".split('');\n            alphabet.forEach(letter => {\n                const card = document.getElementById(`card-${letter}`);\n                if (!card) return;\n\n                let checkTarget = letter;\n                if (currentMode === 'decode') {\n                    // In decode, the input characters are cipher letters\n                    checkTarget = letter;\n                }\n\n                if (usedLettersSet.has(checkTarget)) {\n                    card.classList.add('active');\n                } else {\n                    card.classList.remove('active');\n                }\n            });\n        }\n\n        // Copy Function\n        function copyOutput() {\n            const textToCopy = outputText.value;\n            if (!textToCopy) {\n                showToast(\"Nothing to copy!\", \"warning\");\n                return;\n            }\n\n            // Fallback clipboard method for iframe security\n            const tempArea = document.createElement('textarea');\n            tempArea.value = textToCopy;\n            document.body.appendChild(tempArea);\n            tempArea.select();\n            \n            try {\n                document.execCommand('copy');\n                showToast(\"Copied to clipboard!\");\n            } catch (err) {\n                showToast(\"Failed to copy text\", \"error\");\n            }\n            document.body.removeChild(tempArea);\n        }\n\n        // Swap Input & Output\n        function swapTexts() {\n            const currentOut = outputText.value;\n            inputText.value = currentOut;\n            setMode(currentMode === 'encode' ? 'decode' : 'encode');\n        }\n\n        // Clear All\n        function clearAll() {\n            inputText.value = '';\n            outputText.value = '';\n            inputCharCount.textContent = '0 chars';\n            outputCharCount.textContent = '0 chars';\n            highlightLettersInGrid(new Set());\n        }\n\n        // Load Preset Samples\n        function loadSample(sampleText) {\n            setMode('encode');\n            inputText.value = sampleText;\n            handleTranslate();\n        }\n\n        // Toast message banner\n        function showToast(msg, type = \"success\") {\n            const toast = document.getElementById('toast');\n            const toastMsg = document.getElementById('toast-message');\n            toastMsg.textContent = msg;\n\n            if (type === 'warning') {\n                toast.className = \"fixed top-5 right-5 z-50 transform transition-all duration-300 flex items-center gap-3 bg-amber-600 text-white px-5 py-3 rounded-xl shadow-2xl font-medium border border-amber-400/30\";\n            } else if (type === 'error') {\n                toast.className = \"fixed top-5 right-5 z-50 transform transition-all duration-300 flex items-center gap-3 bg-rose-600 text-white px-5 py-3 rounded-xl shadow-2xl font-medium border border-rose-400/30\";\n            } else {\n                toast.className = \"fixed top-5 right-5 z-50 transform transition-all duration-300 flex items-center gap-3 bg-emerald-600 text-white px-5 py-3 rounded-xl shadow-2xl font-medium border border-emerald-400/30\";\n            }\n\n            toast.classList.remove('translate-y-[-100px]', 'opacity-0');\n            toast.classList.add('translate-y-0', 'opacity-100');\n\n            setTimeout(() => {\n                toast.classList.remove('translate-y-0', 'opacity-100');\n                toast.classList.add('translate-y-[-100px]', 'opacity-0');\n            }, 2500);\n        }\n\n        // Modal for Custom Key Editing\n        function toggleKeyEditor() {\n            const modal = document.getElementById('editor-modal');\n            const isHidden = modal.classList.contains('hidden');\n            \n            if (isHidden) {\n                buildEditorGrid();\n                modal.classList.remove('hidden');\n            } else {\n                modal.classList.add('hidden');\n            }\n        }\n\n        function buildEditorGrid() {\n            const grid = document.getElementById('editor-grid');\n            grid.innerHTML = '';\n            const alphabet = \"ABCDEFGHIJKLMNOPQRSTUVWXYZ\".split('');\n\n            alphabet.forEach(letter => {\n                const wrapper = document.createElement('div');\n                wrapper.className = \"flex items-center gap-2 bg-slate-900/90 p-2 rounded-xl border border-slate-700/60\";\n                wrapper.innerHTML = `\n                    <span class=\"font-mono text-xs text-slate-400 w-4 font-bold\">${letter}:</span>\n                    <input type=\"text\" id=\"edit-${letter}\" maxLength=\"1\" value=\"${cipherMap[letter] || ''}\" \n                        class=\"w-full bg-slate-800 text-purple-300 font-mono text-center uppercase py-1 rounded border border-slate-700 focus:border-purple-500 focus:outline-none text-sm font-bold\">\n                `;\n                grid.appendChild(wrapper);\n            });\n        }\n\n        function saveCustomKey() {\n            const alphabet = \"ABCDEFGHIJKLMNOPQRSTUVWXYZ\".split('');\n            const newMap = {};\n            let isValid = true;\n\n            alphabet.forEach(letter => {\n                const input = document.getElementById(`edit-${letter}`);\n                const val = input.value.trim().toUpperCase();\n                if (!val || !/[A-Z]/.test(val)) {\n                    isValid = false;\n                }\n                newMap[letter] = val;\n            });\n\n            if (!isValid) {\n                showToast(\"All fields must contain a valid letter A-Z!\", \"error\");\n                return;\n            }\n\n            cipherMap = newMap;\n            updateReverseMap();\n            renderAlphabetGrid();\n            handleTranslate();\n            toggleKeyEditor();\n            showToast(\"Custom Cipher Key Saved!\");\n        }\n\n        function resetDefaultKey() {\n            cipherMap = { ...DEFAULT_CIPHER_MAP };\n            updateReverseMap();\n            buildEditorGrid();\n            renderAlphabetGrid();\n            handleTranslate();\n            showToast(\"Key Reset to Standard Shadow Cipher!\");\n        }\n    </script>\n</body>\n</html>";
  OS.register({
    id: 'shadowcipher', name: 'Shadow Cipher', icon: '🕶️', color: '#8B5CF6', cat: 'Secret', hidden: true, w: 600, h: 640,
    build(el) {
      el.innerHTML = '<iframe sandbox="allow-scripts allow-forms allow-modals" style="width:100%;height:100%;border:0;background:#0B0F19"></iframe>';
      el.querySelector('iframe').srcdoc = PAGE;
    }
  });
})();
